def solve(s: str) -> bool:
    """Return True if brackets (), [], {} in the string are balanced and properly nested.
    Other characters are ignored.
    """
    # Use a stack for opening brackets
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
        # ignore other characters
    return not stack

