    """Count the number of islands (connected components of 1s) in a 2D grid.
    Connectivity is 4-directional (up, down, left, right).
    Returns an integer count. Empty grid or grid with no 1s returns 0.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    visited = [[False] * cols for _ in range(rows)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            # explore neighbors
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < rows and 0 <= ny < cols and not visited[nx][ny] and grid[nx][ny] == 1:
