def solve(s):
    """Run-length encoding for any iterable (including strings, lists, generators).
    Returns a list of [element, count] pairs. Empty input yields [] .
    """
    if s is None:
        return []
    try:
        it = iter(s)
    except TypeError:
        return []
    result = []
    try:
        current = next(it)
    except StopIteration:
        return []
    count = 1
    for elem in it:
        if elem == current:
            count += 1
        else:
            result.append([current, count])
            current = elem
            count = 1
    result.append([current, count])
    return result

