def solve(grid):
    """Count the number of islands (connected groups of 1s) in a binary grid.
    Connectivity is 4-directional (up, down, left, right).
    Handles empty grid and ragged rows gracefully.
    Returns an integer count.
    """
    if not grid:
        return 0
    rows = len(grid)
    # Determine column count per row dynamically
    visited = [ [False]*len(grid[r]) for r in range(rows) ]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            # explore neighbors
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < rows and 0 <= ny < len(grid[nx]) and not visited[nx][ny] and grid[nx][ny] == 1:
                    stack.append((nx, ny))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                dfs(i, j)
    return count

