def solve(a: str, b: str) -> int:
    # DP table for Levenshtein distance
    n, m = len(a), len(b)
    # If one string is empty
    if n == 0:
        return m
    if m == 0:
        return n
    # Initialize previous row
    prev = list(range(m + 1))
    for i in range(1, n + 1):
        cur = [i] + [0] * m
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                cost = 0
            else:
                cost = 1
            cur[j] = min(prev[j] + 1,      # deletion
                         cur[j - 1] + 1,  # insertion
                         prev[j - 1] + cost)  # substitution
        prev = cur
    return prev[m]

