def solve(s):
    """Run-length encoding that works for strings and other iterables.
    Returns a list of [character, count] pairs. Non‑iterable or empty input returns [] .
    """
    # Normalize input to a list of characters.
    if isinstance(s, str):
        seq = s
    else:
        try:
            seq = list(s)
        except Exception:
            return []
    if not seq:
        return []
    res = []
    prev = seq[0]
    cnt = 1
    for ch in seq[1:]:
        if ch == prev:
            cnt += 1
        else:
            res.append([prev, cnt])
            prev = ch
            cnt = 1
    res.append([prev, cnt])
    return res

